const $=s=>document.querySelector(s);const catalog=window.BINGE_CATALOG||[];let mode='catalog',lastPlan=null;
const ui={select:$('#titleSelect'),search:$('#catalogSearch'),meta:$('#catalogMeta'),completed:$('#completed'),deadline:$('#deadline'),minutes:$('#minutes'),speed:$('#speed'),error:$('#formError')};
const fmtDate=d=>new Intl.DateTimeFormat('es-ES',{day:'numeric',month:'short',year:d.getFullYear()!==new Date().getFullYear()?'numeric':undefined}).format(d);
const itemWord=(type,n=2)=>type==='movies'?(n===1?'película':'películas'):(n===1?'episodio':'episodios');
function renderOptions(list=catalog){const previous=ui.select.value;ui.select.innerHTML='<option value="">Selecciona del catálogo</option>';['anime','series','movies'].forEach(type=>{const items=list.filter(x=>x.type===type);if(!items.length)return;const group=document.createElement('optgroup');group.label=type==='anime'?'ANIME':type==='series'?'SERIES':'SAGAS DE CINE';items.forEach(item=>{const o=document.createElement('option');o.value=item.id;o.textContent=item.title;group.append(o)});ui.select.append(group)});ui.select.value=previous&&list.some(x=>x.id===previous)?previous:'';syncCatalog()}
function selected(){return catalog.find(x=>x.id===ui.select.value)||null}
function syncCatalog(){const item=selected();if(!item){ui.meta.textContent=ui.search.value?'No hay coincidencias. Usa el modo manual.':'Elige un título para ver sus datos y calcular tu plan.';ui.completed.removeAttribute('max');return}const hours=Math.round(item.total*item.avg/60);ui.meta.innerHTML=`${item.total} ${itemWord(item.type)} · ≈ ${hours} h · ${item.status} · datos revisados 04/09/2026 · <a href="${item.source}" target="_blank" rel="noopener">fuente</a>`;$('#completedUnit').textContent=itemWord(item.type);ui.completed.max=item.total}
renderOptions();const initial=new URLSearchParams(location.search).get('title');if(initial&&catalog.some(x=>x.id===initial)){ui.select.value=initial;syncCatalog()}
ui.search.addEventListener('input',()=>{const q=ui.search.value.trim().toLocaleLowerCase('es');renderOptions(catalog.filter(x=>x.title.toLocaleLowerCase('es').includes(q)))});ui.select.addEventListener('change',syncCatalog);
function clearResult(){lastPlan=null;const result=$('#result');result.className='result-card status-empty';$('#deadlineLabel').textContent='SIN CALCULAR';$('#verdictIcon').textContent='·';$('#verdictKicker').textContent='CUANDO ESTÉS LISTO';$('#verdictTitle').textContent='Tu plan aparecerá aquí.';$('#verdictCopy').textContent='Elige un título o usa el modo manual. No hacemos ninguna cuenta hasta que tú la pidas.';$('#episodesPerSession').textContent='—';$('#sessions').textContent='—';$('#neededMinutes').textContent='—';$('#finishDate').textContent='—';$('#calendarVisual').innerHTML='';$('#scenario').hidden=true}
document.querySelectorAll('.mode-tab').forEach(btn=>btn.addEventListener('click',()=>{mode=btn.dataset.mode;document.querySelectorAll('.mode-tab').forEach(x=>{x.classList.toggle('active',x===btn);x.setAttribute('aria-selected',String(x===btn))});$('#catalogFields').hidden=mode!=='catalog';$('#manualFields').hidden=mode!=='manual';syncManualType();ui.error.textContent='';clearResult()}));
function syncManualType(){const movies=$('#manualType').value==='movies';$('#totalLabel').textContent=movies?'Películas totales':'Capítulos totales';$('#durationLabel').textContent=movies?'Duración media por película':'Duración media por capítulo';$('#completedUnit').textContent=movies?'películas':'episodios';document.querySelector('.season-helper').hidden=movies}
$('#manualType').addEventListener('change',syncManualType);
const dayNames=['L','M','X','J','V','S','D'];dayNames.forEach((day,index)=>{const b=document.createElement('button');b.type='button';b.textContent=day;b.dataset.day=String(index+1);if(index<5)b.classList.add('active');b.setAttribute('aria-pressed',index<5?'true':'false');b.addEventListener('click',()=>{b.classList.toggle('active');b.setAttribute('aria-pressed',String(b.classList.contains('active')));if(lastPlan)calculate()});$('#dayButtons').append(b)});
const defaultDeadline=new Date();defaultDeadline.setDate(defaultDeadline.getDate()+60);ui.deadline.min=new Date().toISOString().slice(0,10);ui.deadline.value=defaultDeadline.toISOString().slice(0,10);
ui.minutes.addEventListener('input',e=>{$('#minutesOut').textContent=`${e.target.value} min`;if(lastPlan)calculate()});ui.speed.addEventListener('change',()=>lastPlan&&calculate());
function manualItem(){const seasons=Number($('#manualSeasons').value),per=Number($('#manualPerSeason').value);const explicit=Number($('#manualTotal').value);const total=explicit||seasons*per;return{id:'manual',title:$('#manualTitle').value.trim()||'Tu maratón',type:$('#manualType').value,total,avg:Number($('#manualDuration').value),status:'Estimación manual'}}
function activeDays(){return [...document.querySelectorAll('#dayButtons button.active')].map(b=>Number(b.dataset.day)%7)}
function sessionDates(until,limit=5000){const days=activeDays(),out=[];let cursor=new Date();cursor.setHours(12,0,0,0);const end=until?new Date(until+'T12:00:00'):null;for(let i=0;i<limit;i++){if((!end||cursor<=end)&&days.includes(cursor.getDay()))out.push(new Date(cursor));if(end&&cursor>=end)break;cursor.setDate(cursor.getDate()+1)}return out}
function planData(){const item=mode==='catalog'?selected():manualItem();const completed=Number(ui.completed.value)||0;const deadline=ui.deadline.value;const days=activeDays();if(!item||!item.total||!item.avg)return{error:'Añade el total y una duración media válida.'};if(completed<0||completed>item.total)return{error:`El progreso debe estar entre 0 y ${item.total}.`};if(!deadline||new Date(deadline+'T23:59:59')<new Date())return{error:'Elige una fecha límite de hoy en adelante.'};if(!days.length)return{error:'Selecciona al menos un día de visionado.'};const dates=sessionDates(deadline),remaining=item.total-completed,speed=Number(ui.speed.value),remainingMinutes=remaining*item.avg/speed,capacity=Number(ui.minutes.value),neededPerSession=dates.length?remainingMinutes/dates.length:Infinity,requiredSessions=Math.ceil(remainingMinutes/capacity);const future=sessionDates(null,Math.max(3650,requiredSessions*12));const finish=remaining===0?new Date():future[Math.max(0,requiredSessions-1)];const margin=dates.length-requiredSessions;const status=remaining===0?'done':neededPerSession<=capacity*.78?'safe':neededPerSession<=capacity?'tight':'late';return{item,completed,remaining,dates,remainingMinutes,capacity,neededPerSession,requiredSessions,finish,margin,status,speed,episodesPerSession:dates.length?remaining/dates.length:Infinity}}
function calculate(){const p=planData();if(p.error){ui.error.textContent=p.error;return}ui.error.textContent='';lastPlan=p;const result=$('#result');result.className=`result-card status-${p.status}`;const copy={safe:['✓','LLEGAS CON MARGEN','Vas sobrado.',`Puedes fallar ${Math.max(0,p.margin)} sesiones y aún llegar a tiempo.`],tight:['≈','LLEGAS JUSTO','Cabe. Sin mucho margen.',`Necesitas mantener el ritmo casi todas las semanas.`],late:['!','NO LLEGAS A ESTE RITMO','Te faltan noches.',`Con ${p.capacity} minutos por sesión terminarías ${Math.abs(p.margin)} sesiones tarde.`],done:['✓','OBJETIVO COMPLETADO','Ya lo has terminado.','No quedan episodios ni películas pendientes.']}[p.status];$('#verdictIcon').textContent=copy[0];$('#verdictKicker').textContent=copy[1];$('#verdictTitle').textContent=copy[2];$('#verdictCopy').textContent=copy[3];$('#episodesPerSession').textContent=p.remaining===0?'0':p.episodesPerSession<10?p.episodesPerSession.toLocaleString('es-ES',{maximumFractionDigits:1}):Math.ceil(p.episodesPerSession);$('#bigUnit').innerHTML=`${itemWord(p.item.type)}<br>por sesión`;$('#sessions').textContent=p.dates.length;$('#neededMinutes').textContent=`${Math.ceil(p.neededPerSession||0)} min`;$('#finishDate').textContent=p.finish?fmtDate(p.finish):'—';$('#deadlineLabel').textContent=fmtDate(new Date(ui.deadline.value+'T12:00:00'));$('#scenario').hidden=false;drawBars(p);updateUrl(p)}
function drawBars(p){const visual=$('#calendarVisual');visual.innerHTML='';const count=Math.min(54,Math.max(10,p.requiredSessions));for(let i=0;i<count;i++){const bar=document.createElement('i');bar.style.height=`${18+(i%8)*7}px`;bar.style.animationDelay=`${i*10}ms`;visual.append(bar)}const position=Math.min(92,Math.max(8,p.dates.length/Math.max(1,p.requiredSessions)*70));document.querySelector('.deadline-rule').style.left=`${position}%`}
function updateUrl(p){const u=new URL(location.href);u.search='';if(mode==='catalog')u.searchParams.set('title',p.item.id);else{u.searchParams.set('manual',p.item.total);u.searchParams.set('avg',p.item.avg);u.searchParams.set('type',p.item.type)}u.searchParams.set('done',p.completed);u.searchParams.set('by',ui.deadline.value);u.searchParams.set('days',activeDays().join(','));u.searchParams.set('min',p.capacity);u.searchParams.set('speed',p.speed);history.replaceState(null,'',u)}
$('#planner').addEventListener('submit',e=>{e.preventDefault();calculate();if(innerWidth<850)$('#result').scrollIntoView({behavior:'smooth'})});
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2200)}
$('#share').addEventListener('click',async()=>{if(!lastPlan)return;const text=`${lastPlan.item.title}: ${$('#verdictKicker').textContent}. ${$('#episodesPerSession').textContent} ${itemWord(lastPlan.item.type)} por sesión.`;try{if(navigator.share)await navigator.share({title:'Binge Deadline',text,url:location.href});else{await navigator.clipboard.writeText(`${text} ${location.href}`);toast('Plan copiado al portapapeles')}}catch(e){if(e.name!=='AbortError')toast('No se pudo compartir')}});
$('#download').addEventListener('click',()=>{if(!lastPlan)return;const c=document.createElement('canvas');c.width=1080;c.height=1920;const x=c.getContext('2d');x.fillStyle='#11130f';x.fillRect(0,0,c.width,c.height);x.fillStyle='#d9ff43';x.fillRect(72,84,32,32);x.fillStyle='#fff';x.font='700 34px sans-serif';x.fillText('BINGE / DEADLINE',128,113);x.fillStyle='#aaa99f';x.font='500 28px monospace';x.fillText(lastPlan.item.type.toUpperCase(),72,310);x.fillStyle='#fff';x.font='800 80px sans-serif';wrap(x,lastPlan.item.title,72,420,900,96);x.fillStyle=lastPlan.status==='late'?'#ff6038':lastPlan.status==='tight'?'#ffc547':'#d9ff43';x.font='800 174px sans-serif';x.fillText($('#episodesPerSession').textContent,72,970);x.fillStyle='#fff';x.font='700 45px sans-serif';x.fillText(`${itemWord(lastPlan.item.type)} por sesión`,72,1040);x.fillStyle='#aaa99f';x.font='500 32px sans-serif';x.fillText(`Fecha límite · ${$('#deadlineLabel').textContent}`,72,1260);x.fillStyle='#fff';x.font='800 70px sans-serif';wrap(x,$('#verdictKicker').textContent,72,1420,900,78);x.strokeStyle='#ff6038';x.lineWidth=8;x.beginPath();x.moveTo(72,1660);x.lineTo(1008,1660);x.stroke();const a=document.createElement('a');a.download='binge-deadline.png';a.href=c.toDataURL('image/png');a.click();toast('Tarjeta descargada')});
function wrap(ctx,text,x,y,max,line){const words=text.split(' ');let row='';for(const word of words){const test=row+word+' ';if(ctx.measureText(test).width>max&&row){ctx.fillText(row,x,y);row=word+' ';y+=line}else row=test}ctx.fillText(row,x,y)}
function restore(){const q=new URLSearchParams(location.search);if(q.has('manual')){document.querySelector('[data-mode="manual"]').click();$('#manualTotal').value=q.get('manual');$('#manualDuration').value=q.get('avg')||45;$('#manualType').value=q.get('type')||'series';syncManualType()}if(q.has('done'))ui.completed.value=q.get('done');if(q.has('by'))ui.deadline.value=q.get('by');if(q.has('min')){ui.minutes.value=q.get('min');$('#minutesOut').textContent=`${q.get('min')} min`}if(q.has('speed'))ui.speed.value=q.get('speed');if(q.has('days')){const days=q.get('days').split(',');document.querySelectorAll('#dayButtons button').forEach(b=>{b.classList.toggle('active',days.includes(b.dataset.day));b.setAttribute('aria-pressed',String(b.classList.contains('active')))})}}
restore();
if(new URLSearchParams(location.search).has('by'))calculate();else clearResult();
if(document.modelContext?.registerTool){
  try{
    const registration=document.modelContext.registerTool({
      name:'calculate_binge_plan',title:'Calcular plan de visionado',
      description:'Configura y calcula un plan para terminar una serie, anime o saga antes de una fecha.',
      inputSchema:{type:'object',properties:{titleId:{type:'string'},completed:{type:'number'},deadline:{type:'string'},minutesPerSession:{type:'number'}},required:['titleId','deadline','minutesPerSession'],additionalProperties:false},
      annotations:{readOnlyHint:false,untrustedContentHint:false},
      execute(input){
        const item=catalog.find(x=>x.id===input.titleId);if(!item)throw new Error('Título no encontrado');
        mode='catalog';ui.select.value=item.id;ui.completed.value=Math.max(0,Number(input.completed)||0);ui.deadline.value=input.deadline;ui.minutes.value=Math.max(20,Math.min(300,Number(input.minutesPerSession)));calculate();
        if(!lastPlan)throw new Error(ui.error.textContent||'No se pudo calcular');
        return{title:item.title,status:lastPlan.status,itemsPerSession:lastPlan.episodesPerSession,minutesNeededPerSession:Math.ceil(lastPlan.neededPerSession),finishDate:lastPlan.finish?.toISOString().slice(0,10)};
      }
    });
    if(registration?.catch)registration.catch(()=>{});
  }catch{}
}
